package main

import (
 "fmt"
 "go/ast"
 "go/parser"
 "go/token"
 "os"
 "path/filepath"
 "sort"
 "strings"
)

type decl struct { key, name, file string; line int; recv string; callers map[string]bool; sites int }

func main() {
 fs:=token.NewFileSet(); ds:=map[string][]*decl{}
 filepath.Walk("internal", func(path string, info os.FileInfo, err error) error {
  if err!=nil || info.IsDir() || !strings.HasSuffix(path,".go") { return nil }
  f,e:=parser.ParseFile(fs,path,nil,0); if e!=nil{return nil}
  ast.Inspect(f, func(n ast.Node) bool { fd,ok:=n.(*ast.FuncDecl); if !ok{return true}; name:=fd.Name.Name; recv:=""; if fd.Recv!=nil { recv=fmt.Sprint(fd.Recv.List[0].Type) }; key:=name+"|"+recv; p:=fs.Position(fd.Pos()); ds[key]=append(ds[key],&decl{key:key,name:name,file:path,line:p.Line,recv:recv,callers:map[string]bool{}}); return false }); return nil
 })
 var all []*decl; for _,x:=range ds { all=append(all,x...) }
 for _,d:=range all {
  filepath.Walk(".",func(path string, info os.FileInfo, err error) error { if err!=nil||info.IsDir()||!strings.HasSuffix(path,".go"){return nil}; f,e:=parser.ParseFile(fs,path,nil,0);if e!=nil{return nil}; var cur string; ast.Inspect(f,func(n ast.Node)bool { if fd,ok:=n.(*ast.FuncDecl);ok { cur=path+":"+fd.Name.Name }; if ce,ok:=n.(*ast.CallExpr);ok { match:=false; switch x:=ce.Fun.(type){case *ast.Ident: match=x.Name==d.name; case *ast.SelectorExpr: match=x.Sel.Name==d.name}; if match && !(path==d.file && strings.Contains(cur,":"+d.name)) {d.callers[cur]=true;d.sites++} }; return true}); return nil })
 }
 sort.Slice(all,func(i,j int)bool{return len(all[i].callers)>len(all[j].callers)})
 for i,d:=range all {if i>=20{break};fmt.Printf("%d callers, %d sites: %s %s:%d recv=%s\n",len(d.callers),d.sites,d.name,d.file,d.line,d.recv)}
}

